const outputArray = sites.map(item => {
  const sshUrl = item.gitUrl;
  const httpsUrl = sshUrl
    .replace(/^git@git3.nexdev.net:/, 'https://git3.nexdev.net/')       
    .replace(/\.git$/, '');             

  const path = httpsUrl.replace(/^https:\/\/git3\.nexdev\.net\//, '');
  return { siteId: item.siteId, siteName: item.siteName , gitUrl: httpsUrl, path, pathEncode: encodeURIComponent(path) };
});

// Return as n8n items
return outputArray.map(i => ({ json: i }));

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let services = [];
for (const item of $input.all()) {
  if(item.json.Stack === $('StartupConfigs').first().json.stack)
  {
    item.json.Service = item.json.Service.replaceAll( /_/gi,  `-`,);
    item.json.srcEnvironment = $('StartupConfigs').first().json.srcEnvironment;
    item.json.desEnvironment = $('StartupConfigs').first().json.desEnvironment;
    item.json.BranchName = $('StartupConfigs').first().json.branchName;
    services.push(item.json);
  }
}

return services;

const commits = $input.first().json.body.commits || [];

return [
  {
    json: {
      rebased: commits.length === 0,
      commitsDiff: commits.map(c => ({ id: c.id, title: c.title }))
    }
  }
];

