  const sshUrl = item.gitUrl;
  const httpsUrl = sshUrl
    .replace(/^git@git3.nexdev.net:/, 'https://git3.nexdev.net/')       
    .replace(/\.git$/, '');             

  const path = httpsUrl.replace(/^https:\/\/git3\.nexdev\.net\//, '');
  return { siteId: item.siteId, siteName: item.siteName , gitUrl: httpsUrl, path, pathEncode: encodeURIComponent(path) };
});

// Return as n8n items
return outputArray.map(i => ({ json: i }));

